package main

import "fmt"

type Point struct {
	X, Y int
}

type Route struct {
	Name  string
	Stops []Point // a slice field: copying a Route copies only its header
}

func main() {
	var zero Point         // zero value: every field zeroed, ready to use
	p := Point{X: 3, Y: 4} // keyed literal: robust to new fields
	q := p                 // assignment copies all fields
	q.X = 100
	fmt.Println(zero, p, q)

	// Structs whose fields are all comparable support == and work as map keys.
	fmt.Println(p == Point{3, 4})
	visits := map[Point]int{{3, 4}: 2}
	visits[p]++
	fmt.Println(visits)

	// A copy is shallow: both Routes share one Stops array.
	r1 := Route{Name: "İzmir-Ankara", Stops: []Point{{0, 0}, {5, 5}}}
	r2 := r1
	r2.Name = "copy"
	r2.Stops[0] = Point{9, 9}
	fmt.Println(r1.Name, r1.Stops)

	// Anonymous structs: one-off shapes, common in table-driven tests.
	cases := []struct {
		in    string
		bytes int
	}{{"i", 1}, {"İ", 2}}
	fmt.Printf("%+v\n", cases)

	// struct{} has size zero: a map[string]struct{} is a set.
	seen := map[string]struct{}{"go": {}}
	_, ok := seen["go"]
	fmt.Println(ok)
}

files.examples/02_embedding.go:
package main

import "fmt"

// Audit is meant to be embedded: it adds fields and methods to any struct.
type Audit struct {
	By      string
	Version int
}

func (a *Audit) Touch(by string) {
	a.By = by
	a.Version++
}

func (a Audit) Label() string { return "audit" }

// Summary calls Label on its own receiver, an Audit. Nothing is virtual.
func (a Audit) Summary() string {
	return fmt.Sprintf("%s v%d by %s", a.Label(), a.Version, a.By)
}

type Order struct {
	Audit // embedded: no field name, the type name is the field name
	ID    int
	Total int // kuruş
}

// Label on Order shadows the promoted Audit.Label.
func (o Order) Label() string { return fmt.Sprintf("order %d", o.ID) }

func main() {
	// Go 1.27: promoted fields (By, Version) may be keys in the literal.
	o := Order{ID: 7, Total: 1250, By: "ayşe", Version: 1}

	o.Touch("mehmet") // promoted method: means o.Audit.Touch("mehmet")
	fmt.Println(o.Version, o.By, o.Audit.By)

	fmt.Println(o.Label())   // Order's own method
	fmt.Println(o.Summary()) // Audit's method, which calls Audit.Label
	fmt.Printf("%+v\n", o)
}

